cd /tmp/vally-eval-trial-aoxSbS && mkdir -p docs/features/pricing tests/CheckoutPricing.UnitTest/Features/Discount
cat > docs/features/pricing/loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier pricing
  A returning customer's loyalty tier is reflected in the checkout total.

  # Not decided by the business: the Platinum tier reduction. No scenario exists for it
  # until the business supplies an expected value (see ac-draft-discount.md, "Not decided").

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer with a 7 cent basket is charged a whole cent amount
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > src/CheckoutPricing.Application/CalculateLoyaltyDiscount.cs <<'EOF'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculateLoyaltyDiscountQuery(int SubtotalCents, LoyaltyTier LoyaltyTier);

public sealed record LoyaltyDiscountQuote(
    int SubtotalCents,
    int DiscountCents,
    int TotalCents,
    LoyaltyTier LoyaltyTier);

public sealed class CalculateLoyaltyDiscount
{
    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query) =>
        new(0, 0, 0, default);
}
EOF
cat > tests/CheckoutPricing.UnitTest/Features/Discount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class LoyaltyDiscountAcceptanceTests
{
    // Bronze customer is charged the Bronze price
    [Fact]
    public void Bronze_customer_is_charged_the_Bronze_price()
    {
        var useCase = new CalculateLoyaltyDiscount();

        var quote = useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~Bronze_customer_is_charged_the_Bronze_price" 2>&1 | tail -15

